/* @lc app=leetcode id=3373 lang=kotlin */ class Solution { fun par(e: Array<IntArray>): IntArray = (e.size + 1).let { n -> e.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.also { d -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { d[it] == -1 }.onEach { v -> d[v] = 1 - d[u] } }.takeIf { it.isNotEmpty() } }.count() } } } fun maxTargetNodes(edges1: Array<IntArray>, edges2: Array<IntArray>): IntArray = par(edges1).let { p1 -> p1.toList().groupingBy { it }.eachCount().let { c1 -> par(edges2).toList().groupingBy { it }.eachCount().values.max().let { b -> IntArray(p1.size) { c1[p1[it]]!! + b } } } } }